def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(v for v in range(1, 10) if any(all(row[c] == v for row in grid) for c in range(w)))
    hr = [r for r in range(h) if all(x == sep for x in grid[r])]
    vc = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    rb = [-1] + hr + [h]
    cb = [-1] + vc + [w]
    out = [row[:] for row in grid]

    # Reflect tile contents across each horizontal divider.
    for k, rsep in enumerate(hr):
        top0, top1 = rb[k] + 1, rsep
        bot0, bot1 = rsep + 1, rb[k + 2]
        if top1 - top0 != bot1 - bot0:
            continue
        for j in range(len(cb) - 1):
            c0, c1 = cb[j] + 1, cb[j + 1]
            top = [grid[r][c0:c1] for r in range(top0, top1)]
            bot = [grid[r][c0:c1] for r in range(bot0, bot1)]
            if any(x for row in top for x in row) and not any(x for row in bot for x in row):
                for dr in range(bot1 - bot0):
                    out[bot0 + dr][c0:c1] = top[-1 - dr][:]
            elif any(x for row in bot for x in row) and not any(x for row in top for x in row):
                for dr in range(top1 - top0):
                    out[top0 + dr][c0:c1] = bot[-1 - dr][:]

    # Reflect tile contents across each vertical divider.
    for k, csep in enumerate(vc):
        left0, left1 = cb[k] + 1, csep
        right0, right1 = csep + 1, cb[k + 2]
        if left1 - left0 != right1 - right0:
            continue
        for i in range(len(rb) - 1):
            r0, r1 = rb[i] + 1, rb[i + 1]
            left = [grid[r][left0:left1] for r in range(r0, r1)]
            right = [grid[r][right0:right1] for r in range(r0, r1)]
            if any(x for row in left for x in row) and not any(x for row in right for x in row):
                for r in range(r0, r1):
                    for dc in range(right1 - right0):
                        out[r][right0 + dc] = grid[r][left1 - 1 - dc]
            elif any(x for row in right for x in row) and not any(x for row in left for x in row):
                for r in range(r0, r1):
                    for dc in range(left1 - left0):
                        out[r][left0 + dc] = grid[r][right1 - 1 - dc]
    return out
